class Solution {
    public boolean isEvenOddTree(TreeNode root){
        Queue<TreeNode> queue=new ArrayDeque<>();
        queue.offer(root);
        int level=0;
        while(!queue.isEmpty()){
            int size=queue.size(),previous=level%2==0?Integer.MIN_VALUE:Integer.MAX_VALUE;
            for(int i=0;i<size;i++){
                TreeNode node=queue.poll();
                if(level%2==0){
                    if(node.val%2==0||node.val<=previous)return false;
                }else if(node.val%2!=0||node.val>=previous)return false;
                previous=node.val;
                if(node.left!=null)queue.offer(node.left);
                if(node.right!=null)queue.offer(node.right);
            }
            level++;
        }
        return true;
    }
}

code.kotlin:
class Solution {
    fun isEvenOddTree(root:TreeNode?):Boolean{
        val queue=java.util.ArrayDeque<TreeNode>();
        queue.add(root!!);
        var level=0;
        while(queue.isNotEmpty()){
            var previous=if(level%2==0)Int.MIN_VALUE else Int.MAX_VALUE;
            repeat(queue.size){
                val node=queue.removeFirst();
                if(level%2==0){
                    if(node.`val`%2==0||node.`val`<=previous)return false
                }else if(node.`val`%2!=0||node.`val`>=previous)return false;
                previous=node.`val`;
                node.left?.let{
                    queue.addLast(it)
                };
                node.right?.let{
                    queue.addLast(it)
                }
            };
            level++
        };
        return true
    }
}

